# Tiny reverse-mode autograd: each node remembers its inputs and local derivatives.
class Val:
    def __init__(self, data, parents=()):
        self.data = data
        self.grad = 0.0
        self.parents = parents          # list of (parent, local_derivative)

    def __add__(self, o):
        return Val(self.data + o.data, [(self, 1.0), (o, 1.0)])

    def __mul__(self, o):
        # saves both inputs: d(xy)/dx = y, d(xy)/dy = x
        return Val(self.data * o.data, [(self, o.data), (o, self.data)])

    def backward(self):
        order, seen = [], set()
        def topo(v):
            if id(v) not in seen:
                seen.add(id(v))
                for p, _ in v.parents:
                    topo(p)
                order.append(v)
        topo(self)
        self.grad = 1.0                  # seed dL/dL = 1
        for v in reversed(order):        # reverse topological order
            for p, local in v.parents:
                p.grad += v.grad * local  # += : sum over every path

x = Val(3.0)
y = Val(2.0)
z = x * y + x                            # x is used twice
print("z = x*y + x with x=3, y=2 ->", z.data)
z.backward()
print("dz/dx =", x.grad, "(y + 1 = 3, two paths summed)")
print("dz/dy =", y.grad, "(x = 3)")
z.backward()                             # second backward without zeroing
print("after 2nd backward, dz/dx =", x.grad, "(accumulated, hence zero_grad)")
